@sealed
class WishtoryCoreImpl extends RustOpaque implements WishtoryCore {
  // Not to be used by end users
  WishtoryCoreImpl.frbInternalDcoDecode(List<dynamic> wire)
    : super.frbInternalDcoDecode(wire, _kStaticData);

  // Not to be used by end users
  WishtoryCoreImpl.frbInternalSseDecode(BigInt ptr, int externalSizeOnNative)
    : super.frbInternalSseDecode(ptr, externalSizeOnNative, _kStaticData);

  static final _kStaticData = RustArcStaticData(
    rustArcIncrementStrongCount:
        RustLib.instance.api.rust_arc_increment_strong_count_WishtoryCore,
    rustArcDecrementStrongCount:
        RustLib.instance.api.rust_arc_decrement_strong_count_WishtoryCore,
    rustArcDecrementStrongCountPtr:
        RustLib.instance.api.rust_arc_decrement_strong_count_WishtoryCorePtr,
  );

  /// Returns how many pulls were removed.
  Future<PlatformInt64> clearAllHistory() => RustLib.instance.api
      .crateApiCoreApiWishtoryCoreClearAllHistory(that: this);

  Future<void> deleteAccount({required GameId game, required String uid}) =>
      RustLib.instance.api.crateApiCoreApiWishtoryCoreDeleteAccount(
        that: this,
        game: game,
        uid: uid,
      );

  Future<List<GameInstall>> discoverGames() =>
      RustLib.instance.api.crateApiCoreApiWishtoryCoreDiscoverGames(that: this);

  /// `format` is one of the ids the Import / Export page offers; `game` and `uid` select one
  /// account, or both `None` for everything.
  Future<void> exportFile({
    required String path,
    required String format,
    GameId? game,
    String? uid,
  }) => RustLib.instance.api.crateApiCoreApiWishtoryCoreExportFile(
    that: this,
    path: path,
    format: format,
    game: game,
    uid: uid,
  );

